const TACTIC = { line_infantry: ['Attack +1 for every 3 redcoats', 'Атака +1 за каждые 3 красных'], ships_of_the_line: ['Attack +1 for every 2 sea cells by the colony', 'Атака +1 за каждые 2 клетки моря у колонии'], native_scouts: ['Terrain does not help the defence', 'Местность не помогает обороне'], hessian_mercenaries: ['4 more redcoats', 'Ещё 4 красных'], surprise_assault: ['Successes on 4, 5 and 6', 'Успех на 4, 5 и 6'], siege_artillery: ['Buildings do not help the defence', 'Постройки не помогают обороне'], loyalist_militia: ['The loyalist gets militia for crosses', 'Лоялист получает ополчение за кресты'], extended_supply_lines: ['A colony falls only to 2 successes', 'Колония падает только от 2 успехов'], gentlemans_war: ['No effect', 'Без эффекта'] };
const EMOJI = { '🟡': 'gold', '🔔': 'bells', '✝️': 'crosses', '🟥': 'ref', '🟨': 'food', '🟫': 'timber', '🟩': 'crops', '🟦': 'goods', '⬜': 'silver', '🌽': 'food', '🐟': 'fish', '🪵': 'timber', '🍂': 'crops', '🦫': 'crops', '📦': 'goods', '🪙': 'silver', '⚔️': 'sword', '💢': 'anger', '📖': 'book', '🎓': 'cap' };
const draw = (s, size = 16) => Object.entries(EMOJI).reduce((x, [e, k]) => x.replaceAll(e, icon(k, size)), s.replace(/\{(\w+)\}/g, (_, k) => icon(k, size)).replace(/<\/?i>/g, '')).replace(/ ?\/ /g, '. ').replace(/\.\. /g, '. ').replace(/[🛖💨🎲💀👨🏻‍🌾🛠️]/gu, '').trim();
const text = (en, key, size) => draw(lang() === 'ru' ? Engine.texts[key] || en : en, size);
export const Texts = { father: (id, n) => text(FATHER[id] || '', `father.${id}`, n), event: (id, n) => text(EVENT[id] || '', `event.${id}`, n), tactic: (id) => pick(TACTIC[id] || ['', '']) };
/* What an agent is good at, from its modifiers. */
export function traits(id) {
  const out = [], n = (x) => (x > 0 ? `+${x}` : x);
  const sword = { infantry: 0, ship: 0 };
  for (const m of D.agents[id].mods) {
    if (m.mod === 'production') out.push(`${n(m.add)} ${m.icons ? m.icons.map((i) => icon({ corn: 'food', leaf: 'crops', fur: 'crops' }[i] || i, 15)).join('') : icon('gather', 15)}${m.terrain ? icon(m.terrain, 15) : ''}`);
    if (m.mod === 'move') out.push(`${n(m.add)} ${icon('move', 15)}${icon(m.token, 15)}`);
    if (m.mod === 'combat' && m.terrain && !m.vs) out.push(`${n(m.add)} ${icon('sword', 14)}${icon(m.terrain, 15)}`);
    if (m.mod === 'combat') sword[m.token] += m.vs || m.terrain ? 0 : m.add;
    if (m.mod === 'cost') out.push(`${m.add} ${m.of === 'hire' ? icon('gold', 15) : icon('timber', 15)}`);
    if (m.mod === 'sellPrice') out.push(`${n(m.add)} ${icon('gold', 15)}`);
    if (m.mod === 'bombard') out.push(pick(['bombards', 'обстрел']));
  }
  // Gathering only: said once, after the gathering bonus if there is one.
  if (D.agents[id].mods.some((m) => m.mod === 'onlyProduce')) { const i = out.findIndex((x) => x.includes('ic-gather')); if (i >= 0) out[i] += ` ${pick(['only', 'только'])}`; else out.push(`${icon('gather', 15)} ${pick(['only', 'только'])}`); }
  if (sword.infantry) out.unshift(`+${sword.infantry} ${icon('sword', 14)}`); else if (sword.ship) out.unshift(`+${sword.ship} ${icon('sword', 14)}${icon('ship', 15)}`);
  return out;
}
export const trait = (c) => `${eduIcon(D.agents[c].edu)} ${traits(c).join(' ')}`;
export const work = (id) => { const b = D.buildings[id], w = b.work; if (b.storage) return `+${b.storage} ${L('places', 'мест')}`; if (b.defence) return `+${b.defence} ${icon('sword', 14)}`; if (!w) return ''; if (w.kind === 'ocean') return `2 ${icon('fish', 16)}`; if (w.kind === 'sell') return L('sells 1 good', 'продаёт 1 товар'); if (w.kind === 'repair') return L('full repair', 'полный ремонт'); if (w.kind === 'teach') return `${L('teaches', 'учит')} ${icon(w.maxEdu === 2 ? 'cap' : 'book', 15)}`; return `${w.consumes ? `${w.consumes.amount}${icon(w.consumes.res, 16)} ▸ ` : ''}${w.amount}${icon(Places.ico(w.icon), 16)}`; };
